// Script dispatcher is used to select a response based on the incoming request.
// Here are few examples showing how to match based on path, query param, header and body

// path
def requestPath = mockRequest.getPath()
log.info "Path: "+ requestPath

// query parameter
def queryString = mockRequest.getRequest().getQueryString()
log.info "QueryString: " + queryString

if( requestPath.contains("personErweitert/1") )
{
	return "EWO-Response1"
}
if( requestPath.contains("personErweitert/2") )
{
	log.info("Es kommt eine Timeout!");
	Thread.sleep(100000);
	log.info("Timeout!");
}
if( requestPath.contains("personErweitert/3") )
{
  	return "EWO-Invalid-Response1"
}

